 'B: r(t)P(1-P/K)+S(t), r=a+b sin, S=c+d t':lambda p:(p[0]+p[1]*np.sin(p[2]*t+p[3]))*P*(1-P/p[4])+p[5]+p[6]*t,
 'C: a*P*(1-P/K)+ b*exp(c t)+ d':lambda p:p[0]*P*(1-P/p[1])+p[2]*np.exp(p[3]*t)+p[4],
 'D: a*P+b*P^2+ c*exp(dt)+ e*t*P':lambda p:p[0]*P+p[1]*P**2+p[2]*np.exp(p[3]*t)+p[4]+p[5]*t*P+p[6]*t*P**2,
}
